/**
 * Immutable BRIPe reality binding.
 *
 * Morpheus remains the owner of reality identity. ESSG remains the owner of
 * immutable evidence snapshots. This contract binds those existing owners at
 * the point where Structural Reality is sealed and BRIPe is allowed to decide.
 * It deliberately does not introduce a product-owned reality store.
 */
import { type RealitySelectionIdentity } from "../corporate-brain/morpheus-reality-selection";
export declare const IMMUTABLE_REALITY_SELECTION_SCHEMA_VERSION: "bripe.immutable_reality_selection.v1";
export type ImmutableRealityState = "CURRENT" | "TARGET" | "ASSESSMENT" | "SCENARIO" | "ATTACK_SCENARIO" | "COMPROMISED" | "RECOVERY";
export interface ImmutableRealitySelection {
    readonly schema_version: typeof IMMUTABLE_REALITY_SELECTION_SCHEMA_VERSION;
    /** Tenant partition that owns the selected canonical subject. */
    readonly tenant_id: string;
    /** Canonical entity that BRIPe may reason about for this decision. */
    readonly canonical_subject_id: string;
    /** Morpheus universe/reality selected for this one execution. */
    readonly universe_id: string;
    readonly selected_reality_id: string;
    readonly reality_state: ImmutableRealityState;
    readonly scenario_id: string | null;
    /** Immutable ESSG / Corporate Brain materialization used by this decision. */
    readonly snapshot: {
        readonly essg_snapshot_id: string;
        readonly essg_snapshot_hash: string;
        readonly cb_snapshot_id: string;
    };
    /** Exact evidence population allowed into the selected reality. */
    readonly evidence_boundary: {
        readonly evidence_ids: readonly string[];
        readonly evidence_fingerprint: string;
    };
    /** Existing producer lineage; never regenerated by a downstream consumer. */
    readonly derivation_lineage: {
        readonly lineage_token: string;
        readonly source_snapshot_ids: readonly string[];
    };
    /** Read-only Morpheus proof; BRIPe and products must only carry it. */
    readonly morpheus_selection: RealitySelectionIdentity;
    /** Stable selection fingerprint used for equality and CER boundary checks. */
    readonly selection_fingerprint: string;
}
